import{_ as t}from"./chunks/feedback-qrcode.dVwgjorL.js";import{bQ as i,aL as n,u as a,G as s}from"./chunks/framework.C1gZXFVa.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"ansible-offline-install","text":"Install Ansible with no internet, in one command","tagline":"Ansible packaged into a single offline bundle - copy it to your air-gapped machine, run one command, done. No network needed during installation.","image":{"src":"/terminal.svg","alt":"Terminal illustration of running install.sh on an offline server"},"actions":[{"theme":"brand","text":"Quick Start","link":"/en/guide/quick-start"},{"theme":"alt","text":"Download a Bundle","link":"/en/guide/download"},{"theme":"alt","text":"GitHub Repository","link":"https://github.com/ghl1024/ansible-offline-install"}]},"features":[{"icon":"📴","title":"Fully offline","details":"At install time pip uses a local wheelhouse with --no-index and never touches the network. Works in air-gapped datacenters and intranets."},{"icon":"🖥️","title":"8 platform combinations","details":"EL 9 family / Ubuntu 24.04 / Ubuntu 22.04 / Debian 12, on both x86_64 and ARM64. Every bundle is built and install-tested by CI on real machines."},{"icon":"🛡️","title":"System environment untouched","details":"Ansible goes into a dedicated venv folder (/opt/ansible-offline for root, ~/ansible-offline for regular users). Delete the folder to uninstall completely."},{"icon":"📌","title":"Pinned and reproducible","details":"requirements.txt pins ansible-core==2.18.19, so every machine gets an identical environment."},{"icon":"🧩","title":"Collections bundled","details":"Bundles ship ansible.posix and community.general (with dependencies), the two most commonly used collections, ready to use offline."},{"icon":"🌏","title":"Bilingual scripts and docs","details":"The installer and builder print Chinese by default; --lang en or ANSIBLE_OFFLINE_LANG=en switches to English. This documentation is bilingual too."}]},"headers":[],"relativePath":"en/index.md","filePath":"en/index.md"}'),l={name:"en/index.md"};function o(r,e,d,h,c,p){return n(),a("div",null,[...e[0]||(e[0]=[s(`<h2 id="running-in-60-seconds" tabindex="-1">Running in 60 seconds <a class="header-anchor" href="#running-in-60-seconds" aria-label="Permalink to &quot;Running in 60 seconds&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1. Extract (pick the right bundle in the platform matrix first,</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#    and verify it with the .sha256 file from the download page)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ansible-offline-install-2.0.0-el9-x86_64-py311.tar.gz</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ansible-offline-install-2.0.0-bundle</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2. Install - fully offline, self-verifies at the end</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install.sh</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 3. Confirm</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ansible</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><ul><li>Details in the <a href="/en/guide/quick-start">Quick Start</a>; bundle selection in the <a href="/en/guide/platforms">Platform Matrix</a>.</li></ul><h2 id="what-this-does-in-plain-words" tabindex="-1">What this does, in plain words <a class="header-anchor" href="#what-this-does-in-plain-words" aria-label="Permalink to &quot;What this does, in plain words&quot;">​</a></h2><blockquote><p>Many company and datacenter servers are not allowed to reach the internet (an &quot;air-gapped&quot; environment). On such a machine, <code>pip install ansible</code> always fails, because it needs to download packages.</p></blockquote><blockquote><p>This project works around that in three steps:</p></blockquote><ol><li>On a computer <strong>with</strong> internet access, pack everything needed into one archive file (or simply download a ready-made, tested bundle from this project, see <a href="/en/guide/quick-start">Quick Start</a>).</li><li>Copy that file into the intranet (USB stick, bastion host, internal file server - anything works).</li><li>On the offline server, run the installer inside the bundle. Ansible goes into a <strong>dedicated folder</strong>, nothing on the system is modified, and deleting that folder uninstalls it completely.</li></ol><h2 id="source-repositories-and-mirrors" tabindex="-1">Source repositories and mirrors <a class="header-anchor" href="#source-repositories-and-mirrors" aria-label="Permalink to &quot;Source repositories and mirrors&quot;">​</a></h2><blockquote><p>The project is published on four platforms with identical content; the mirrors are usually faster for downloads inside China:</p></blockquote><table tabindex="0"><thead><tr><th>Platform</th><th>URL</th><th>Notes</th></tr></thead><tbody><tr><td>GitHub</td><td><a href="https://github.com/ghl1024/ansible-offline-install" target="_blank" rel="noreferrer">https://github.com/ghl1024/ansible-offline-install</a></td><td>Primary repository: development and releases</td></tr><tr><td>Gitee</td><td><a href="https://gitee.com/ghl1024/ansible-offline-install" target="_blank" rel="noreferrer">https://gitee.com/ghl1024/ansible-offline-install</a></td><td>China mirror, releases auto-synced via CNB</td></tr><tr><td>GitCode</td><td><a href="https://gitcode.com/haydenguo/ansible-offline-install" target="_blank" rel="noreferrer">https://gitcode.com/haydenguo/ansible-offline-install</a></td><td>China mirror</td></tr><tr><td>CNB</td><td><a href="https://cnb.cool/ghl1024/ansible-offline-install" target="_blank" rel="noreferrer">https://cnb.cool/ghl1024/ansible-offline-install</a></td><td>China mirror</td></tr></tbody></table><h2 id="💡-feedback-community" tabindex="-1">💡 Feedback &amp; Community <a class="header-anchor" href="#💡-feedback-community" aria-label="Permalink to &quot;💡 Feedback &amp; Community&quot;">​</a></h2><blockquote><p>Questions or new ideas: open an <a href="https://github.com/ghl1024/ansible-offline-install/issues" target="_blank" rel="noreferrer">Issue</a> in the primary repository - you can also browse Issues for problems others hit and their solutions. If you can, include your OS version (the output of <code>cat /etc/os-release</code>) and the error message you saw.</p></blockquote><ul><li>Or scan to join the community group:</li></ul><img class="feedback-qrcode" src="`+t+'" alt="Community group QR code">',14)])])}const b=i(l,[["render",o]]);export{m as __pageData,b as default};
